const leads = $json.leads || [];

function validateLead(lead) {
  const missing = [];
  if (!lead.company) missing.push('company');
  if (!lead.contactName) missing.push('contactName');
  if (!lead.email) missing.push('email');
  if (!lead.requestedService) missing.push('requestedService');
  if (!lead.consentToContact) missing.push('contact consent');
  return { valid: missing.length === 0, missing };
}

function scoreLead(lead) {
  const validation = validateLead(lead);
  if (!validation.valid) {
    return {
      ...lead,
      score: 0,
      category: 'Needs Review',
      validationStatus: validation.missing.join(', '),
      recommendedNextAction: 'Do not contact until reviewed by a human.'
    };
  }

  let score = 20;
  score += lead.budget >= 1000 ? 30 : lead.budget >= 500 ? 20 : 8;
  score += lead.urgency === 'high' ? 25 : lead.urgency === 'medium' ? 15 : 5;
  score += lead.businessFit === 'strong' ? 25 : lead.businessFit === 'medium' ? 15 : 5;

  const category = score >= 75 ? 'Hot' : score >= 50 ? 'Warm' : 'Cold';

  return {
    ...lead,
    score,
    category,
    validationStatus: 'complete',
    recommendedNextAction: category === 'Hot'
      ? 'Human review, then consider follow-up.'
      : category === 'Warm'
        ? 'Review scope and budget before follow-up.'
        : 'Hold unless more details are provided.'
  };
}

return leads.map(lead => ({ json: scoreLead(lead) }));
